import{_ as o,o as t,c as a,a4 as r}from"./chunks/framework.bruR1JhL.js";const c=JSON.parse('{"title":"Support","description":"Get help with Tilepress, report a problem, suggest a feature, or help the project.","frontmatter":{"title":"Support","description":"Get help with Tilepress, report a problem, suggest a feature, or help the project."},"headers":[],"relativePath":"support.md","filePath":"support.md","lastUpdated":1795509372000}'),s={name:"support.md"};function i(n,e,l,h,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h1><p>Tilepress is a free, community project. Here&#39;s how to get help, and how to help in return.</p><h2 id="get-help" tabindex="-1">Get help <a class="header-anchor" href="#get-help" aria-label="Permalink to &quot;Get help&quot;">​</a></h2><ol><li><strong>Read the guide for your tool.</strong> Every tool has a step-by-step page in the <a href="/tilepress/docs/">documentation</a>, with its options and limits.</li><li><strong>Check the questions below</strong>, and <a href="#troubleshooting">troubleshooting</a>.</li><li><strong>Ask the community</strong> in <a href="https://github.com/epicabdou/tilepress/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>.</li><li><strong>Found a bug?</strong> <a href="https://github.com/epicabdou/tilepress/issues/new/choose" target="_blank" rel="noreferrer">Open an issue</a>. The form asks for what you need to include.</li></ol><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><h3 id="is-tilepress-really-free" tabindex="-1">Is Tilepress really free? <a class="header-anchor" href="#is-tilepress-really-free" aria-label="Permalink to &quot;Is Tilepress really free?&quot;">​</a></h3><p>Yes. It&#39;s free software under the GNU GPL v3: free to use for anything, at home or at work, with no account, ads, trial or premium tier. You may also change it and share it, as long as what you share stays under the same license.</p><h3 id="are-my-files-uploaded-anywhere" tabindex="-1">Are my files uploaded anywhere? <a class="header-anchor" href="#are-my-files-uploaded-anywhere" aria-label="Permalink to &quot;Are my files uploaded anywhere?&quot;">​</a></h3><p>No. Tilepress opens, changes and saves files on your own computer, and sends no telemetry. It only goes online when it has to fetch something you asked for: the LaTeX engine (once), an AI model the first time you use an AI tool, or a web page you give to HTML to PDF or HTML to Image. <a href="/tilepress/docs/privacy">Privacy, in detail</a></p><h3 id="is-tilepress-related-to-ilovepdf-or-iloveimg" tabindex="-1">Is Tilepress related to iLovePDF or iLoveIMG? <a class="header-anchor" href="#is-tilepress-related-to-ilovepdf-or-iloveimg" aria-label="Permalink to &quot;Is Tilepress related to iLovePDF or iLoveIMG?&quot;">​</a></h3><p>No. Tilepress is an independent, open-source project. Its tools have familiar names so you can find your way, but it works entirely on your PC.</p><h3 id="does-it-run-on-mac-or-linux" tabindex="-1">Does it run on Mac or Linux? <a class="header-anchor" href="#does-it-run-on-mac-or-linux" aria-label="Permalink to &quot;Does it run on Mac or Linux?&quot;">​</a></h3><p>Not yet: Tilepress is a Windows 10 and 11 app. The code is on <a href="https://github.com/epicabdou/tilepress" target="_blank" rel="noreferrer">GitHub</a> if you&#39;d like to help port it.</p><h3 id="do-i-need-microsoft-office" tabindex="-1">Do I need Microsoft Office? <a class="header-anchor" href="#do-i-need-microsoft-office" aria-label="Permalink to &quot;Do I need Microsoft Office?&quot;">​</a></h3><p>Only for Word to PDF, Excel to PDF and PowerPoint to PDF, which need Microsoft Office or the free LibreOffice. Everything else, including PDF to Word, Excel and PowerPoint, works without it.</p><h3 id="why-does-windows-warn-me-about-the-installer" tabindex="-1">Why does Windows warn me about the installer? <a class="header-anchor" href="#why-does-windows-warn-me-about-the-installer" aria-label="Permalink to &quot;Why does Windows warn me about the installer?&quot;">​</a></h3><p>The installer isn&#39;t code-signed yet, so SmartScreen doesn&#39;t know it. Choose <strong>More info → Run anyway</strong>. You can <a href="/tilepress/download#install">check the download&#39;s checksum</a> first.</p><h3 id="where-are-my-settings-and-history" tabindex="-1">Where are my settings and history? <a class="header-anchor" href="#where-are-my-settings-and-history" aria-label="Permalink to &quot;Where are my settings and history?&quot;">​</a></h3><p>In <code>%LOCALAPPDATA%\\Tilepress</code>: your settings, the <a href="/tilepress/docs/history">history</a>, the LaTeX engine and any AI models you&#39;ve downloaded. Uninstalling keeps this folder; delete it to start fresh.</p><h3 id="why-is-the-first-latex-compile-slow" tabindex="-1">Why is the first LaTeX compile slow? <a class="header-anchor" href="#why-is-the-first-latex-compile-slow" aria-label="Permalink to &quot;Why is the first LaTeX compile slow?&quot;">​</a></h3><p>On first launch Tilepress downloads its LaTeX engine (about 19 MB) and caches the common packages. That takes a couple of minutes, once. The rest of the app works meanwhile.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="the-window-stays-blank" tabindex="-1">The window stays blank <a class="header-anchor" href="#the-window-stays-blank" aria-label="Permalink to &quot;The window stays blank&quot;">​</a></h3><p>Tilepress draws its window with Microsoft Edge WebView2. Install the <a href="https://developer.microsoft.com/microsoft-edge/webview2/" target="_blank" rel="noreferrer">WebView2 Runtime</a> and start Tilepress again.</p><h3 id="word-excel-or-powerpoint-to-pdf-fails" tabindex="-1">Word, Excel or PowerPoint to PDF fails <a class="header-anchor" href="#word-excel-or-powerpoint-to-pdf-fails" aria-label="Permalink to &quot;Word, Excel or PowerPoint to PDF fails&quot;">​</a></h3><p>These need Microsoft Office or LibreOffice installed. The status button at the top right (click <strong>Ready</strong>) shows which one Tilepress found.</p><h3 id="ocr-finds-no-text-or-the-wrong-language" tabindex="-1">OCR finds no text, or the wrong language <a class="header-anchor" href="#ocr-finds-no-text-or-the-wrong-language" aria-label="Permalink to &quot;OCR finds no text, or the wrong language&quot;">​</a></h3><p>Choose the document&#39;s language in OCR PDF. Windows OCR only knows languages installed in <strong>Settings → Time &amp; language → Language</strong> with &quot;Optical character recognition&quot;; installing Tesseract OCR adds many more.</p><h3 id="an-ai-tool-can-t-download-its-model" tabindex="-1">An AI tool can&#39;t download its model <a class="header-anchor" href="#an-ai-tool-can-t-download-its-model" aria-label="Permalink to &quot;An AI tool can&#39;t download its model&quot;">​</a></h3><p>The first use of Upscale Image or Remove background downloads a model (4.5 MB and 179 MB). Check your internet connection and try again; after that the tool works offline.</p><h3 id="my-antivirus-flags-tilepress" tabindex="-1">My antivirus flags Tilepress <a class="header-anchor" href="#my-antivirus-flags-tilepress" aria-label="Permalink to &quot;My antivirus flags Tilepress&quot;">​</a></h3><p>Apps packaged with PyInstaller, as Tilepress is, are sometimes flagged by mistake. You can check your download against the release&#39;s <code>SHA256SUMS.txt</code>, read the source, or build it yourself. Please report false positives to your antivirus vendor.</p><h3 id="sending-a-useful-bug-report" tabindex="-1">Sending a useful bug report <a class="header-anchor" href="#sending-a-useful-bug-report" aria-label="Permalink to &quot;Sending a useful bug report&quot;">​</a></h3><p>Include your Tilepress version (click <strong>Ready</strong>, top right), your Windows version, the tool, and what you did. The log file at <code>%LOCALAPPDATA%\\Tilepress\\toolbox.log</code> helps a lot; check it for anything private before attaching it.</p><h2 id="help-the-project" tabindex="-1">Help the project <a class="header-anchor" href="#help-the-project" aria-label="Permalink to &quot;Help the project&quot;">​</a></h2><ul><li><strong>Star it</strong> on <a href="https://github.com/epicabdou/tilepress" target="_blank" rel="noreferrer">GitHub</a>, and tell people who still upload their files to online tools.</li><li><strong>Report bugs and suggest tools</strong> in <a href="https://github.com/epicabdou/tilepress/issues" target="_blank" rel="noreferrer">Issues</a>.</li><li><strong>Improve these docs</strong>: every page has an &quot;Improve this page on GitHub&quot; link.</li><li><strong>Contribute code</strong>: start with the <a href="https://github.com/epicabdou/tilepress/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">contributing guide</a>.</li><li><strong>Security problems</strong>: please report them privately, as described in the <a href="https://github.com/epicabdou/tilepress/blob/main/SECURITY.md" target="_blank" rel="noreferrer">security policy</a>.</li></ul>',36)])])}const f=o(s,[["render",i]]);export{c as __pageData,f as default};
